function [loss, grads] = modelLoss(net, X, T)
    Y = forward(net, X);
    loss = crossentropy(Y, T);
    grads = dlgradient(loss, net.Learnables);
end
% called as: [loss, grads] = dlfeval(@modelLoss, net, dlX, dlT);

velocity = [];
for epoch = 1:numEpochs
    for iter = 1:numIterations
        [X, T] = next(mbq);
        [loss, grads] = dlfeval(@modelLoss, net, X, T);
        [net, velocity] = sgdmupdate(net, grads, velocity, 0.01, 0.9);
    end
end

avgGrad = []; avgSqGrad = []; iteration = 0;
for epoch = 1:20
    shuffle(mbq);
    while hasdata(mbq)
        iteration = iteration + 1;
        [X, T] = next(mbq);
        [loss, grads] = dlfeval(@modelLoss, net, X, T);
        [net, avgGrad, avgSqGrad] = adamupdate(net, grads, ...
            avgGrad, avgSqGrad, iteration, 1e-3);
    end
end

velocity = [];
learnRate = 0.05;
for epoch = 1:30
    learnRate = 0.05 / (1 + 0.01*epoch);
    while hasdata(mbq)
        [X, T] = next(mbq);
        [loss, grads] = dlfeval(@modelLoss, net, X, T);
        [net, velocity] = sgdmupdate(net, grads, velocity, learnRate, 0.9);
    end
    reset(mbq); shuffle(mbq);
end

